    }
    for (i = 0; i < 8; ++i) {
        const struct enhancement_entry *e = &enhancement_catalog[24 + i];
        if (!(obj->o_enh_props & e->bit)) obj->o_enh_values[i] = 0;
        else if (obj->o_enh_values[i] < e->dice
