int
equipment_bonus(const struct obj *obj, int stat)
{
    int i, total = 0;
    uint64 bits = enhancement_active(obj);
    if (!obj) return 0;
    for (i = 0; i < 8; ++i) {
        const struct enhancement_entry *e = &enhancement_catalog[24 + i];
